import React, { useState, useEffect } from 'react';
import {
  Card,
  CardContent,
  Typography,
  Grid,
  Button,
  Box,
  Chip,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  FormGroup,
  FormControlLabel,
  Checkbox,
  CircularProgress,
  Alert,
  Divider,
  LinearProgress
} from '@mui/material';
import {
  Store,
  LocationOn as MapPin,
  Business as Building,
  BarChart,
  TrendingUp,
  Inventory as Package,
  FlashOn as Zap,
  CheckCircle,
  Warning as AlertCircle
} from '@mui/icons-material';

interface StoreData {
  location: string;
  city: string;
  total_walls: number;
  lob_breakdown: Record<string, string>;
  capacity_summary: Record<string, number>;
  wall_details: Record<string, {
    walls: string[];
    total_capacity: number | string;
    wall_count: number;
    products: string[];
  }>;
}

interface LOBRecommendation {
  priority_score: number;
  current_walls: number;
  current_capacity: number;
  target_allocation: number;
  recommendation: string;
}

interface StoreRecommendations {
  optimization: {
    current_distribution: Record<string, number>;
    optimal_distribution: Record<string, number>;
    changes_needed: Record<string, any>;
  };
  lob_priorities: Record<string, LOBRecommendation>;
  summary: string;
}

interface GenerationResult {
  store_name: string;
  generation_mode: string;
  total_planograms: number;
  lob_categories: string[];
  planograms: Record<string, string[]>;
}

const StoreSelector: React.FC = () => {
  const [storeAnalysis, setStoreAnalysis] = useState<any>(null);
  const [selectedStore, setSelectedStore] = useState<string>('');
  const [storeDetails, setStoreDetails] = useState<StoreData | null>(null);
  const [recommendations, setRecommendations] = useState<StoreRecommendations | null>(null);
  const [loading, setLoading] = useState(false);
  const [generationMode, setGenerationMode] = useState<'LOB_WISE' | 'PRODUCT_WISE' | 'FULL_STORE'>('LOB_WISE');
  const [selectedLOBs, setSelectedLOBs] = useState<string[]>([]);
  const [generating, setGenerating] = useState(false);
  const [generationResult, setGenerationResult] = useState<GenerationResult | null>(null);

  useEffect(() => {
    fetchStoreAnalysis();
  }, []);

  useEffect(() => {
    if (selectedStore) {
      fetchStoreDetails();
      fetchRecommendations();
    }
  }, [selectedStore]);

  const fetchStoreAnalysis = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/stores/analysis');
      const data = await response.json();

      if (data.success) {
        setStoreAnalysis(data.data);
      }
    } catch (error) {
      console.error('Error fetching store analysis:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchStoreDetails = async () => {
    if (!selectedStore) return;

    try {
      const response = await fetch(`/api/stores/${encodeURIComponent(selectedStore)}/lob-details`);
      const data = await response.json();

      if (data.success) {
        setStoreDetails(data.data);
      }
    } catch (error) {
      console.error('Error fetching store details:', error);
    }
  };

  const fetchRecommendations = async () => {
    if (!selectedStore) return;

    try {
      const response = await fetch(`/api/stores/${encodeURIComponent(selectedStore)}/recommendations`);
      const data = await response.json();

      if (data.success) {
        setRecommendations(data.data);
      }
    } catch (error) {
      console.error('Error fetching recommendations:', error);
    }
  };

  const generatePlanograms = async () => {
    if (!selectedStore) return;

    try {
      setGenerating(true);
      const response = await fetch(`/api/stores/${encodeURIComponent(selectedStore)}/generate-planograms`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          mode: generationMode,
          selected_lobs: generationMode === 'PRODUCT_WISE' ? selectedLOBs : undefined
        })
      });

      const data = await response.json();

      if (data.success) {
        // Poll for job completion
        pollJobStatus(data.job_id);
      }
    } catch (error) {
      console.error('Error generating planograms:', error);
      setGenerating(false);
    }
  };

  const pollJobStatus = async (jobId: string) => {
    const interval = setInterval(async () => {
      try {
        const response = await fetch(`/api/jobs/${jobId}`);
        const data = await response.json();

        if (data.success && data.job) {
          if (data.job.status === 'completed') {
            setGenerationResult(data.job.result);
            setGenerating(false);
            clearInterval(interval);
          } else if (data.job.status === 'failed') {
            console.error('Job failed:', data.job.error);
            setGenerating(false);
            clearInterval(interval);
          }
        }
      } catch (error) {
        console.error('Error polling job status:', error);
        setGenerating(false);
        clearInterval(interval);
      }
    }, 2000);
  };

  const getStoreOptions = () => {
    if (!storeAnalysis?.store_selector) return [];
    return Object.keys(storeAnalysis.store_selector);
  };

  const getLOBOptions = () => {
    if (!storeDetails?.wall_details) return [];
    return Object.keys(storeDetails.wall_details).filter(lob => 
      lob !== 'audio' && storeDetails.wall_details[lob]?.wall_count > 0
    );
  };

  const formatLOBName = (lob: string) => {
    return lob.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
  };

  const getRecommendationColor = (recommendation: string) => {
    switch (recommendation) {
      case 'EXPAND_RECOMMENDED': return 'bg-green-100 text-green-800';
      case 'CONSIDER_REDUCING': return 'bg-red-100 text-red-800';
      case 'AT_CAPACITY': return 'bg-yellow-100 text-yellow-800';
      default: return 'bg-blue-100 text-blue-800';
    }
  };

  if (loading) {
    return (
      <Box display="flex" alignItems="center" justifyContent="center" minHeight="300px">
        <CircularProgress />
        <Typography sx={{ ml: 2 }}>Loading store analysis...</Typography>
      </Box>
    );
  }

  return (
    <Box>
      {/* Header */}
      <Box display="flex" alignItems="center" sx={{ mb: 3 }}>
        <Store sx={{ mr: 1 }} />
        <Typography variant="h4" component="h1">Store LOB Distribution Analyzer</Typography>
      </Box>

      {/* Store Selection */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Box display="flex" alignItems="center" sx={{ mb: 2 }}>
            <MapPin sx={{ mr: 1 }} />
            <Typography variant="h6">Store Selection</Typography>
          </Box>

          <FormControl fullWidth sx={{ mb: 2 }}>
            <InputLabel>Select a store</InputLabel>
            <Select
              value={selectedStore}
              onChange={(e) => setSelectedStore(e.target.value)}
              label="Select a store"
            >
              {getStoreOptions().map(store => (
                <MenuItem key={store} value={store}>
                  {store} ({storeAnalysis.store_selector[store]?.city})
                </MenuItem>
              ))}
            </Select>
          </FormControl>

          {selectedStore && storeDetails && (
            <Grid container spacing={2}>
              <Grid item xs={12} md={4}>
                <Box display="flex" alignItems="center">
                  <Building sx={{ mr: 1, color: 'text.secondary' }} />
                  <Typography variant="body2" color="text.secondary" sx={{ mr: 1 }}>Location:</Typography>
                  <Typography variant="body2" fontWeight="medium">{storeDetails.location}</Typography>
                </Box>
              </Grid>
              <Grid item xs={12} md={4}>
                <Box display="flex" alignItems="center">
                  <MapPin sx={{ mr: 1, color: 'text.secondary' }} />
                  <Typography variant="body2" color="text.secondary" sx={{ mr: 1 }}>City:</Typography>
                  <Typography variant="body2" fontWeight="medium">{storeDetails.city}</Typography>
                </Box>
              </Grid>
              <Grid item xs={12} md={4}>
                <Box display="flex" alignItems="center">
                  <Package sx={{ mr: 1, color: 'text.secondary' }} />
                  <Typography variant="body2" color="text.secondary" sx={{ mr: 1 }}>Total Walls:</Typography>
                  <Typography variant="body2" fontWeight="medium">{storeDetails.total_walls}</Typography>
                </Box>
              </Grid>
            </Grid>
          )}
        </CardContent>
      </Card>

      {/* LOB Breakdown */}
      {selectedStore && storeDetails && (
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Box display="flex" alignItems="center" sx={{ mb: 2 }}>
              <BarChart sx={{ mr: 1 }} />
              <Typography variant="h6">Current LOB Breakdown</Typography>
            </Box>

            <Grid container spacing={2}>
              {Object.entries(storeDetails.wall_details).map(([lob, details]) => {
                if (details.wall_count === 0) return null;
                return (
                  <Grid item xs={12} md={6} lg={4} key={lob}>
                    <Card variant="outlined" sx={{ p: 2 }}>
                      <Box display="flex" justifyContent="space-between" alignItems="center">
                        <Typography variant="body2" fontWeight="medium">{formatLOBName(lob)}</Typography>
                        <Chip label={`${details.wall_count} walls`} size="small" />
                      </Box>
                      <Typography variant="caption" color="text.secondary" sx={{ mt: 1 }}>
                        Capacity: {details.total_capacity}
                      </Typography>
                    </Card>
                  </Grid>
                );
              })}
            </Grid>
          </CardContent>
        </Card>
      )}

      {/* Recommendations */}
      {recommendations && (
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Box display="flex" alignItems="center" sx={{ mb: 2 }}>
              <TrendingUp sx={{ mr: 1 }} />
              <Typography variant="h6">Optimization Recommendations</Typography>
            </Box>

            <Alert severity="info" sx={{ mb: 2 }}>
              {recommendations.summary}
            </Alert>

            {recommendations.optimization?.changes_needed && Object.keys(recommendations.optimization.changes_needed).length > 0 && (
              <Box>
                <Typography variant="h6" sx={{ mb: 1 }}>Recommended Changes:</Typography>
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                  {Object.entries(recommendations.optimization.changes_needed).map(([lob, change]: [string, any]) => (
                    <Box key={lob} display="flex" justifyContent="space-between" alignItems="center" 
                         sx={{ p: 1, border: 1, borderColor: 'grey.300', borderRadius: 1 }}>
                      <Typography variant="body2" fontWeight="medium">{formatLOBName(lob)}</Typography>
                      <Chip 
                        label={`${change.action} ${change.walls_affected} wall(s)`}
                        color={change.action === 'ADD' ? 'success' : 'error'}
                        size="small"
                      />
                    </Box>
                  ))}
                </Box>
              </Box>
            )}
          </CardContent>
        </Card>
      )}

      {/* Planogram Generation */}
      {selectedStore && (
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Box display="flex" alignItems="center" sx={{ mb: 2 }}>
              <Zap sx={{ mr: 1 }} />
              <Typography variant="h6">Generate Planograms</Typography>
            </Box>

            <Box sx={{ mb: 2 }}>
              <FormControl fullWidth>
                <InputLabel>Generation Mode</InputLabel>
                <Select
                  value={generationMode}
                  onChange={(e) => setGenerationMode(e.target.value as any)}
                  label="Generation Mode"
                >
                  <MenuItem value="LOB_WISE">Generate all LOB categories</MenuItem>
                  <MenuItem value="PRODUCT_WISE">Generate specific categories</MenuItem>
                  <MenuItem value="FULL_STORE">Full store optimization</MenuItem>
                </Select>
              </FormControl>
            </Box>

            {generationMode === 'PRODUCT_WISE' && (
              <Box sx={{ mb: 2 }}>
                <Typography variant="body2" fontWeight="medium" sx={{ mb: 1 }}>
                  Select LOB Categories:
                </Typography>
                <FormGroup>
                  <Grid container>
                    {getLOBOptions().map(lob => (
                      <Grid item xs={6} md={4} key={lob}>
                        <FormControlLabel
                          control={
                            <Checkbox
                              checked={selectedLOBs.includes(lob)}
                              onChange={(e) => {
                                if (e.target.checked) {
                                  setSelectedLOBs([...selectedLOBs, lob]);
                                } else {
                                  setSelectedLOBs(selectedLOBs.filter(l => l !== lob));
                                }
                              }}
                            />
                          }
                          label={<Typography variant="body2">{formatLOBName(lob)}</Typography>}
                        />
                      </Grid>
                    ))}
                  </Grid>
                </FormGroup>
              </Box>
            )}

            <Button
              variant="contained"
              fullWidth
              onClick={generatePlanograms}
              disabled={generating || (generationMode === 'PRODUCT_WISE' && selectedLOBs.length === 0)}
              startIcon={generating ? <CircularProgress size={20} /> : <Zap />}
            >
              {generating ? 'Generating Planograms...' : 'Generate Planograms'}
            </Button>
          </CardContent>
        </Card>
      )}

      {/* Generation Results */}
      {generationResult && (
        <Card>
          <CardContent>
            <Box display="flex" alignItems="center" sx={{ mb: 2 }}>
              <CheckCircle sx={{ mr: 1, color: 'success.main' }} />
              <Typography variant="h6">Generation Complete</Typography>
            </Box>

            <Grid container spacing={2} sx={{ mb: 3 }}>
              <Grid item xs={12} md={4}>
                <Card variant="outlined" sx={{ textAlign: 'center', p: 2 }}>
                  <Typography variant="h4" color="primary">{generationResult.total_planograms}</Typography>
                  <Typography variant="body2" color="text.secondary">Total Planograms</Typography>
                </Card>
              </Grid>
              <Grid item xs={12} md={4}>
                <Card variant="outlined" sx={{ textAlign: 'center', p: 2 }}>
                  <Typography variant="h4" color="success.main">{generationResult.lob_categories.length}</Typography>
                  <Typography variant="body2" color="text.secondary">LOB Categories</Typography>
                </Card>
              </Grid>
              <Grid item xs={12} md={4}>
                <Card variant="outlined" sx={{ textAlign: 'center', p: 2 }}>
                  <Typography variant="h6" color="secondary">{generationResult.generation_mode}</Typography>
                  <Typography variant="body2" color="text.secondary">Generation Mode</Typography>
                </Card>
              </Grid>
            </Grid>

            <Box sx={{ mb: 3 }}>
              <Typography variant="h6" sx={{ mb: 1 }}>Generated Categories:</Typography>
              {generationResult.lob_categories.map(category => (
                <Box key={category} display="flex" justifyContent="space-between" alignItems="center" 
                     sx={{ p: 1, border: 1, borderColor: 'grey.300', borderRadius: 1, mb: 1 }}>
                  <Typography variant="body2" fontWeight="medium">{formatLOBName(category)}</Typography>
                  <Chip label={`${generationResult.planograms[category]?.length || 0} planograms`} size="small" variant="outlined" />
                </Box>
              ))}
            </Box>

            <Box>
              <Typography variant="h6" sx={{ mb: 1 }}>Generated Files:</Typography>
              <Box sx={{ maxHeight: 200, overflow: 'auto' }}>
                {Object.entries(generationResult.planograms).map(([category, files]) => (
                  <Box key={category} sx={{ mb: 2 }}>
                    <Typography variant="body2" fontWeight="medium" color="text.primary">
                      {formatLOBName(category)}:
                    </Typography>
                    {files.map((file, index) => (
                      <Typography key={index} variant="caption" component="div" 
                                sx={{ fontFamily: 'monospace', bgcolor: 'grey.100', p: 0.5, borderRadius: 0.5, mb: 0.5 }}>
                        {file}
                      </Typography>
                    ))}
                  </Box>
                ))}
              </Box>
            </Box>
          </CardContent>
        </Card>
      )}
    </Box>
  );
};

export default StoreSelector;
